#ifndef OMARCHIUM_BROWSER_THEME_OMARCHY_THEME_SYNC_STATE_H_
#define OMARCHIUM_BROWSER_THEME_OMARCHY_THEME_SYNC_STATE_H_

namespace omarchium {

// Whether the browser is following an Omarchy theme. Dependency-free so
// low-level Chromium code (e.g. ThemeService) can ask.
//
// While it is, Omarchy's managed `BrowserThemeColor` policy (which Omarchy
// writes to tint stock Chromium) is ignored: the live sync supersedes it,
// and the autogenerated theme it would build paints over the synced colors.
bool IsOmarchyThemeSyncActive();
void SetOmarchyThemeSyncActive(bool active);

}  // namespace omarchium

#endif  // OMARCHIUM_BROWSER_THEME_OMARCHY_THEME_SYNC_STATE_H_
